import bedrock;

// This is a grammar lesson: define the loop syntax ourselves, without importing
// Tower's executable foreach. The parse tree works; execution needs a replacement.
[number]
token Number = /[0-9]+/;
// Define the pieces used by the loop below.
parse Variable = Identifier;
parse Expression = Identifier | Number;
parse Statement = Expression ';';

parse ForEach = 'for' '(' $Variable 'in' $Expression ')' '{' $Statement* '}';
parse Statement |= ForEach;

for (item in items) {
    item;
    for (child in children) {
        child;
    }
}

// Change the spelling from 'for' to 'foreach' for the code below.
parse ForEach = 'foreach' '(' $Variable 'in' $Expression ')' '{' $Statement* '}';
foreach (entry in entries) {}

import tower;

// Tower supplies expressions and control flow. Add one small statement ourselves:
// the replacement expands into an ordinary assignment before execution.
parse Statement |= 'increment' $name:Identifier ';'
    => replace { $name = $name + 1; };

var count = 0;
var total = 0;
while count < 5 {
    increment count;
    total += count;
}
print(total);

// Aliases share the same typed storage.
var alias = &total;
(*alias)++;
print(total);

import foundation;

// Foundation supplies basic statements, functions and types. Add ++ below.

// These helpers increment i32 locations; postfix returns old, prefix returns new.
fn post_increment(p: i32*): i32 {
    var old: i32 = *p;
    *p = old + 1;
    return old;
}

fn pre_increment(p: i32*): i32 {
    var next: i32 = *p;
    next = next + 1;
    *p = next;
    return next;
}

// Extending CoreCall covers assigned results, standalone statements and arguments.
// Neither spelling exists until these rules expand it into an ordinary call.
parse CoreCall |= $target:CoreLocation '++'
    => replace { post_increment(&$target) };
parse CoreCall |= '++' $target:CoreLocation
    => replace { pre_increment(&$target) };

var value: i32 = 5;
var before: i32 = value++;
// 5: the old value, then 6: the updated variable.
print(before);
print(value);
var after: i32 = ++value;
// 7: the new value, then 7: the updated variable.
print(after);
print(value);

// Discarding the result uses the same rules.
value++;
++value;
// Calls accept increment results too: prints 9, then value becomes 10.
print(value++);

import tower;

// An initializer supplies the type; ordinary integer literals default to i32.
// Functions can be defined later. Their parameter and return types stay explicit.
var answer = add_one(41);
print(answer);
var correct = answer == 42;
print(correct);

// Addresses retain their pointed-to type: pointer is i32*.
var pointer = &answer;
*pointer = 43;
print(answer);

// A typed call supplies u32 here, including inside the function's initializer.
var unsigned_result = twice(21);
print(unsigned_result);

fn add_one(value: i32): i32 {
    return value + 1;
}

fn twice(value: u32): u32 {
    return value + value;
}

import tower;

// Type and integer arguments determine the fields of a concrete struct.
fn buffer(T: type, size: usize): type {
    struct Result {
        data: T[size];
    }
    return Result;
}

fn stack(T: type): type {
    struct Result {
        // Four inline slots are enough for the two sample values below.
        storage: buffer(T, 4);
        count: usize;
    }
    return Result;
}

// This small example assumes there is space to push and a value to pop.
fn push(T: type, values: stack(T)*, value: T): void {
    values.storage.data[values.count] = value;
    values.count++;
}

fn pop(T: type, values: stack(T)*): T {
    values.count--;
    return values.storage.data[values.count];
}

// This stack stores its fixed array inline; it never allocates heap memory.
var values: stack(i32) = default;
// The typed stack argument lets Tower infer T = i32 for these calls.
push(&values, 10);
push(&values, 20);
print(pop(&values));
print(pop(&values));

import tower;

// One subject evaluation, one selected arm, and a scope for every body.
fn description(value: i32): i32 {
    match value {
        0 => {
            return 10;
        }
        1 | 2 => {
            return 20;
        }
        _ => {
            return 30;
        }
    }
}

for (var value = 0; value < 4; value++) {
    print(description(value));
}

import tower;
import library.stack;
import library.queue;

var lifo: stack(i32);
var fifo: queue(i32);
stack_init(&lifo);
queue_init(&fifo);

// Init leaves both containers empty; the first push allocates their heap storage.
// The stack grows with realloc. The queue allocates a larger buffer and copies
// its values in order. Both start with room for eight values and grow as needed.
// Push returns false if memory is unavailable or the requested size is too large.
// A failed push keeps the old values; dispose below releases each owned buffer.
for (var value = 10; value <= 30; value += 10) {
    if !stack_push(&lifo, value) {
        print("Stack allocation failed");
    }
    if !queue_push(&fifo, value) {
        print("Queue allocation failed");
    }
}

// Empty pop returns false and leaves the output unchanged.
var value = 0;
while stack_pop(&lifo, &value) {
    print(value);
}
while queue_pop(&fifo, &value) {
    print(value);
}
stack_dispose(&lifo);
queue_dispose(&fifo);

import tower;

// Tower adds nested expressions to Foundation's functions, calls and returns.
var answer = factorial(6);
print(answer);

// Forward calls and recursion use the same foundation nodes in both backends.
fn factorial(n: i32): i32 {
    if n <= 1 {
        return 1;
    }
    return factorial(n -1) *n;
}

fn increment(value: i32*): void {
    (*value)++;
}

var pointer = &answer;
increment(pointer);
print(answer);

import tower;

// A struct groups typed fields. A pointer lets a function update the original.
struct Pair {
    first: i32;
    second: i32;
}

fn accumulate(pair: Pair*): void {
    pair.first += pair.second;
}

var pair: Pair = {
    first: 20, second: 22
};
var pointer = &pair;
accumulate(pointer);
print(pair.first);
print(pointer.second);

// A pointer to a field aliases its original storage.
var field = &pair.second;
*field = 7;
print(pair.second);

import tower;

// Raw buffers and views are ordinary structs. There are no implicit bounds checks.
struct Bytes {
    data: u8*;
    length: usize;
    capacity: usize;
}

var InitialByteCapacity: usize = 8;
var TextLength: usize = 5;

// realloc may move the buffer. Keep its old address until growth succeeds;
// on failure it still owns its old storage and the caller can safely free it.
fn append(buffer: Bytes*, value: u8): bool {
    if buffer.length == buffer.capacity {
        var maximum = ~convert(usize, 0);
        if buffer.capacity > maximum / 2 {
            return false;
        }
        var capacity = buffer.capacity == 0 ? InitialByteCapacity: buffer.capacity *2;
        var grown = realloc(u8, buffer.data, capacity);
        if grown is null {
            return false;
        }
        buffer.data = grown;
        buffer.capacity = capacity;
    }
    buffer.data[buffer.length] = value;
    buffer.length++;
    return true;
}

// Zero initialization creates an empty buffer; append allocates on first use.
var buffer: Bytes = default;
var text: u8* = "Tower";
for (var i: usize = 0; i < TextLength; i++) {
    if !append(&buffer, text[i]) {
        print("Byte buffer allocation failed");
        break;
    }
}
print(buffer.length);
if buffer.length != 0 {
    print(buffer.data[0]);
}
var fixed: i32[3];
fixed[0] = 10;
fixed[1] = 20;
fixed[2] = 12;
var values: i32* = &fixed[0];
print(values[0] + values[1] + values[2]);
free(buffer.data);

import bedrock;

[number] token Number = /[0-9]+/;

// Core grammar: ordinary expressions, blocks, and a primitive loop form.
parse Atom = Identifier | Number;
parse Term = Atom;
parse Expression = Term;
parse Atom |= '(' Expression ')';
parse Term |= Term '*' Atom;
parse Expression |= Expression '+' Term;
parse Statement = Expression ';';
parse Block = '{' $Statement* '}';
parse Statement |= Block;
parse Loop = 'loop' '(' $item:Identifier 'in' $collection:Expression ')' $body:Block;
parse Statement |= Loop;

// Replacement bodies are parsed as trees. Captures retain their grouping.
parse Expression |= 'increment' '(' $value:Expression ')'
    => replace { $value + 1 };
parse Expression |= 'add_one' '(' $value:Expression ')'
    => replace { increment($value) };

// foreach is defined here and expands to the primitive Loop tree.
parse Statement |= 'foreach' '(' $item:Identifier 'in' $collection:Expression ')' $body:Block
    => replace { loop ($item in $collection) $body };

// Repeated captures can be inserted more than once, including empty lists.
parse Statement |= 'twice' '{' $body:Statement* '}'
    => replace { { $body $body } };

increment(2 * 3);
add_one(4);
foreach (item in items) {
    increment(item);
    foreach (child in children) {
        child;
    }
}
twice {
    add_one(7);
}

import bedrock;

// These are ordinary Tower declarations, editable while you type.
// Add hyphens and non-ASCII Unicode characters to identifiers.
[identifier] token Identifier = /[A-Za-z_\u{80}-\u{10ffff}][A-Za-z_0-9\u{80}-\u{10ffff}-]*/;
// Decimal numbers, with an optional fractional part.
[number] token Number = /[0-9]+(\.[0-9]+)?/;
// Extra token types work too. Longest match makes 0xff a Hex, not Number 0.
[number] token Hex = /0x[0-9A-Fa-f]+/;
[comment] skip HashComment = /#[^\r\n]*/;

parse Value = Identifier | Number | String | Hex;
parse Statement = Value ';';
parse Pair = Identifier ':' Number ';';
parse Statement |= Pair;
// Later grammar literals would use backticks too, so define the rules above first.
[string] token String = /`[^`\r\n]*`/;
player-name;
café;
3.14;
`hello from Tower`;
0xff;
# Comments are defined in Tower too.
// Token replacement takes effect only after this declaration.
[identifier] token Identifier = /@[A-Za-z_][A-Za-z_0-9]*/;
@player;
// This also changes subsequent declaration names; the rules above are already installed.
@score: 42.5;

// Execute prints 42. Run tests checks the inline and adjacent score tests.
// Change the expectation in score_test.tower to see an assertion location.
import tower;
import score;
print(double_score(21));

import tower;
import library.testing;

fn double_score(points: i32): i32 { return points + points; }

test() {
    assert(double_score(0) == 0, "Expected zero points");
}

import tower;
import library.testing;
import score;
import test_points;

fn total_points(): i32 { return double_score(sample_points()); }

test() {
    var per_player = total_points() / player_count();
    assert(per_player == 21, "Expected 21 points per player");
}

import tower;

fn sample_points(): i32 { return 21; }
fn player_count(): i32 { return 2; }
